    map: shadowTex,
    transparent: true,
    emissive: 0x000000,
    emissiveIntensity: 1,
    metalness: 0,
    roughness: 1,
    side: THREE.DoubleSide
  });
  toDispose.materials.push(shadowMat);

  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -0.36, 0);
  shadow.rotation.x = -Math.PI / 2;
  shadow.renderOrder = 1;
  group.add(shadow);

  // Backdrop plane (7x6, z=-3) with vertical gradient
