/**
 * Generate radial gradient texture for contact shadow.
 * Black center (opacity 0.6) fading to transparent edges over 1.5-unit radius.
 */
function generateRadialGradientTexture() {
  const width = 256;
  const height = 256;
  const data = new Uint8Array(width * height * 4);
  const center = width / 2;
  const falloffRadius = center * 1.2;

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const dx = x - center;
      const dy = y - center;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const normalized = Math.min(1, dist / falloffRadius);
      const alpha = Math.max(0, 1 - normalized) * 0.6 * 255;

      const idx = (y * width + x) * 4;
      data[idx] = 0;
      data[idx + 1] = 0;
      data[idx + 2] = 0;
      data[idx + 3] = Math.round(alpha);
    }
  }

  const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat, THREE.UnsignedByteType);
  texture.needsUpdate = true;
  return texture;
}

/**
 * Generate vertical gradient texture for backdrop.
 * Colors: #0b0b10 (0%) → #101017 (70%) → #16161d (100%)
 */
function generateVerticalGradientTexture() {
  const width = 512;
  const height = 512;
  const data = new Uint8Array(width * height * 4);

  const colors = [
    { stop: 0.0, rgb: [0x0b, 0x0b, 0x10] },
    { stop: 0.7, rgb: [0x10, 0x10, 0x17] },
    { stop: 1.0, rgb: [0x16, 0x16, 0x1d] }
  ];

  for (let y = 0; y < height; y++) {
    const t = y / height;

    let c;
    if (t <= 0.7) {
      const s = t / 0.7;
      c = [
        Math.round(colors[0].rgb[0] + (colors[1].rgb[0] - colors[0].rgb[0]) * s),
        Math.round(colors[0].rgb[1] + (colors[1].rgb[1] - colors[0].rgb[1]) * s),
        Math.round(colors[0].rgb[2] + (colors[1].rgb[2] - colors[0].rgb[2]) * s)
      ];
    } else {
      const s = (t - 0.7) / 0.3;
      c = [
        Math.round(colors[1].rgb[0] + (colors[2].rgb[0] - colors[1].rgb[0]) * s),
        Math.round(colors[1].rgb[1] + (colors[2].rgb[1] - colors[1].rgb[1]) * s),
        Math.round(colors[1].rgb[2] + (colors[2].rgb[2] - colors[1].rgb[2]) * s)
      ];
    }

    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 4;
      data[idx] = c[0];
      data[idx + 1] = c[1];
      data[idx + 2] = c[2];
      data[idx + 3] = 255;
    }
  }

  const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat, THREE.UnsignedByteType);
  texture.needsUpdate = true;
  return texture;
}
